import { useDeferredValue, useId, useMemo, useState, type KeyboardEvent } from 'react';
import {
  Combobox,
  Input,
  InputBase,
  SegmentedControl,
  Text,
  useVirtualizedCombobox,
  type InputBaseProps,
} from '@mantine/core';
import { useLocalStorage, useUncontrolled } from '@mantine/hooks';
import {
  buildGridModel,
  COLUMNS,
  DROPDOWN_WIDTH,
  moveByRows,
  PAGE_ROWS,
  type GridModel,
} from './grid-model';
import {
  getIconComponent,
  getIcons,
  searchIcons,
  type IconPickerValue,
  type IconStyle,
} from './icon-index';
import { IconByName } from './IconByName';
import { IconGrid } from './IconGrid';
import classes from './IconPicker.module.css';

export type { IconPickerValue, IconStyle } from './icon-index';

const RECENT_LIMIT = COLUMNS;

const STYLE_OPTIONS = [
  { value: 'outline', label: 'Outline' },
  { value: 'filled', label: 'Filled' },
];

export interface IconPickerProps extends Omit<
  InputBaseProps,
  'value' | 'defaultValue' | 'onChange'
> {
  value?: IconPickerValue | null;
  defaultValue?: IconPickerValue | null;
  onChange?: (value: IconPickerValue | null) => void;
  placeholder?: string;
  /** localStorage key of the recently picked icons */
  recentStorageKey?: string;
}

function isKnownIcon(item: IconPickerValue) {
  return getIconComponent(item.name, item.style) !== undefined;
}

function createModel(style: IconStyle, query: string, recent: IconPickerValue[]) {
  const entries = searchIcons(getIcons(style), query);
  return buildGridModel(entries, style, query.trim() === '' ? recent : []);
}

function findInGrid(model: GridModel, name: string | undefined) {
  if (name === undefined) {
    return -1;
  }
  return model.cells.findIndex((cell, index) => index >= model.gridStart && cell.name === name);
}

export function IconPicker({
  value,
  defaultValue,
  onChange,
  label = 'Project icon',
  placeholder = 'Pick an icon',
  recentStorageKey = 'icon-picker-recent',
  ...others
}: IconPickerProps) {
  const [current, setCurrent] = useUncontrolled<IconPickerValue | null>({
    value,
    defaultValue,
    finalValue: null,
    onChange,
  });
  const [storedRecent, setRecent] = useLocalStorage<IconPickerValue[]>({
    key: recentStorageKey,
    defaultValue: [],
    getInitialValueInEffect: false,
  });
  const recent = useMemo(() => storedRecent.filter(isKnownIcon), [storedRecent]);

  const [search, setSearch] = useState('');
  const [style, setStyle] = useState<IconStyle>('outline');
  const [highlightedIndex, setHighlightedIndex] = useState(-1);
  const [hoveredIndex, setHoveredIndex] = useState(-1);

  // Filtering thousands of icons and rebuilding the grid waits until typing pauses
  const query = useDeferredValue(search);
  const model = useMemo(() => createModel(style, query, recent), [style, query, recent]);

  const uid = useId();
  const getOptionId = (index: number) => `${uid}-${model.cells[index]?.key}`;

  const pick = (index: number) => {
    const cell = model.cells[index];
    if (!cell) {
      return;
    }
    const next = { name: cell.name, style: cell.style };
    setCurrent(next);
    setRecent((items) =>
      [next, ...items.filter((item) => item.name !== next.name || item.style !== next.style)].slice(
        0,
        RECENT_LIMIT
      )
    );
    combobox.closeDropdown();
  };

  const combobox = useVirtualizedCombobox({
    totalOptionsCount: model.cells.length,
    getOptionId,
    selectedOptionIndex: highlightedIndex,
    setSelectedOptionIndex: setHighlightedIndex,
    onSelectedOptionSubmit: pick,
    onDropdownOpen: () => {
      const openStyle = current?.style ?? 'outline';
      const openModel = createModel(openStyle, '', recent);
      const selected = findInGrid(openModel, current?.name);
      setStyle(openStyle);
      setSearch('');
      setHighlightedIndex(selected !== -1 ? selected : openModel.cells.length > 0 ? 0 : -1);
      combobox.focusSearchInput();
    },
    onDropdownClose: () => {
      setHoveredIndex(-1);
      combobox.focusTarget();
    },
  });

  const handleSearchChange = (nextSearch: string) => {
    setSearch(nextSearch);
    setHoveredIndex(-1);
    setHighlightedIndex(0);
  };

  const handleStyleChange = (nextStyle: IconStyle) => {
    // Keep the highlighted icon when it exists in the other style
    const name = model.cells[highlightedIndex]?.name;
    const nextModel = createModel(nextStyle, query, recent);
    const index = findInGrid(nextModel, name);
    setStyle(nextStyle);
    setHoveredIndex(-1);
    setHighlightedIndex(index !== -1 ? index : nextModel.cells.length > 0 ? 0 : -1);
  };

  const handleSearchKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    const last = model.cells.length - 1;
    const from = highlightedIndex;
    const move = (getIndex: () => number) => {
      event.preventDefault();
      if (last >= 0) {
        setHighlightedIndex(from === -1 ? 0 : getIndex());
      }
    };

    switch (event.key) {
      case 'ArrowRight':
        move(() => Math.min(from + 1, last));
        break;
      case 'ArrowLeft':
        move(() => Math.max(from - 1, 0));
        break;
      case 'ArrowDown':
        move(() => moveByRows(model, from, 1));
        break;
      case 'ArrowUp':
        move(() => moveByRows(model, from, -1));
        break;
      case 'PageDown':
        move(() => moveByRows(model, from, PAGE_ROWS));
        break;
      case 'PageUp':
        move(() => moveByRows(model, from, -PAGE_ROWS));
        break;
      case 'Home':
        move(() => 0);
        break;
      case 'End':
        move(() => last);
        break;
      case 'Enter':
        if (!event.nativeEvent.isComposing) {
          event.preventDefault();
          combobox.clickSelectedOption();
        }
        break;
      case 'Escape':
        combobox.closeDropdown();
        break;
    }
  };

  const handleTargetKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      combobox.openDropdown('keyboard');
    }
    if ((event.key === 'Backspace' || event.key === 'Delete') && current) {
      event.preventDefault();
      setCurrent(null);
    }
  };

  const previewCell = model.cells[hoveredIndex !== -1 ? hoveredIndex : highlightedIndex];

  return (
    <Combobox
      store={combobox}
      width={DROPDOWN_WIDTH}
      position="bottom-start"
      classNames={{ dropdown: classes.dropdown }}
    >
      <Combobox.Target withAriaAttributes={false}>
        <InputBase
          component="button"
          type="button"
          pointer
          label={label}
          aria-haspopup="listbox"
          aria-expanded={combobox.dropdownOpened}
          leftSection={
            current ? (
              <IconByName name={current.name} iconStyle={current.style} size={18} stroke={1.5} />
            ) : undefined
          }
          rightSection={
            current ? (
              <Input.ClearButton aria-label="Clear icon" onClick={() => setCurrent(null)} />
            ) : (
              <Combobox.Chevron />
            )
          }
          rightSectionPointerEvents={current ? 'all' : 'none'}
          onClick={() => combobox.toggleDropdown()}
          onKeyDown={handleTargetKeyDown}
          {...others}
        >
          {current ? current.name : <Input.Placeholder>{placeholder}</Input.Placeholder>}
        </InputBase>
      </Combobox.Target>

      <Combobox.Dropdown>
        <Combobox.Search
          aria-label="Search icons"
          placeholder="Search icons"
          value={search}
          withKeyboardNavigation={false}
          onChange={(event) => handleSearchChange(event.currentTarget.value)}
          onKeyDown={handleSearchKeyDown}
        />

        <SegmentedControl
          fullWidth
          size="xs"
          className={classes.styleControl}
          aria-label="Icon style"
          data={STYLE_OPTIONS}
          value={style}
          onChange={(next) => handleStyleChange(next as IconStyle)}
          // Keep focus in the search field
          onMouseDown={(event) => event.preventDefault()}
        />

        <Combobox.Options aria-label="Icons">
          {model.cells.length === 0 ? (
            <Combobox.Empty className={classes.empty}>
              Nothing found for "{query.trim()}"
            </Combobox.Empty>
          ) : (
            <IconGrid
              key={`${style}:${query}`}
              opened={combobox.dropdownOpened}
              model={model}
              value={current}
              highlightedIndex={highlightedIndex}
              getOptionId={getOptionId}
              onPick={pick}
              onHover={setHoveredIndex}
            />
          )}
        </Combobox.Options>

        <Combobox.Footer className={classes.footer} role="status">
          {previewCell ? (
            <>
              <IconByName
                name={previewCell.name}
                iconStyle={previewCell.style}
                size={20}
                stroke={1.5}
              />
              <Text size="sm">{previewCell.name}</Text>
            </>
          ) : (
            <Text size="xs">Arrow keys to move, Enter to pick</Text>
          )}
        </Combobox.Footer>
      </Combobox.Dropdown>
    </Combobox>
  );
}

import { createElement } from 'react';
import type { IconProps } from '@tabler/icons-react';
import { getIconComponent, type IconStyle } from './icon-index';

interface IconByNameProps extends IconProps {
  name: string;
  iconStyle: IconStyle;
}

export function IconByName({ name, iconStyle, ...others }: IconByNameProps) {
  const component = getIconComponent(name, iconStyle);
  return component ? createElement(component, others) : null;
}

import { useEffect, useRef, useState } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';
import { Combobox, ScrollArea, Text } from '@mantine/core';
import {
  COLUMNS,
  getOffsetToCenter,
  getOffsetToReveal,
  GRID_HEIGHT,
  LABEL_HEIGHT,
  ROW_HEIGHT,
  type GridModel,
} from './grid-model';
import type { IconPickerValue } from './icon-index';
import { IconByName } from './IconByName';
import classes from './IconPicker.module.css';

interface IconGridProps {
  opened: boolean;
  model: GridModel;
  value: IconPickerValue | null;
  highlightedIndex: number;
  getOptionId: (index: number) => string;
  onPick: (index: number) => void;
  onHover: (index: number) => void;
}

const GRID_WIDTH = COLUMNS * ROW_HEIGHT;

/** Renders only the visible rows. Remount it (with `key`) when the list changes. */
export function IconGrid({
  opened,
  model,
  value,
  highlightedIndex,
  getOptionId,
  onPick,
  onHover,
}: IconGridProps) {
  const viewportRef = useRef<HTMLDivElement>(null);
  const [initialOffset] = useState(() => getOffsetToCenter(model, highlightedIndex));

  const virtualizer = useVirtualizer({
    count: model.rows.length,
    getScrollElement: () => viewportRef.current,
    estimateSize: (index) => (model.rows[index].kind === 'label' ? LABEL_HEIGHT : ROW_HEIGHT),
    getItemKey: (index) => model.rows[index].key,
    initialOffset,
    initialRect: { width: GRID_WIDTH, height: GRID_HEIGHT },
    overscan: 3,
  });

  // Keep the highlighted cell in view while it moves
  useEffect(() => {
    if (highlightedIndex < 0) {
      return;
    }
    const current = virtualizer.scrollOffset ?? 0;
    const next = getOffsetToReveal(model, highlightedIndex, current);
    if (next !== current) {
      virtualizer.scrollToOffset(next);
    }
  }, [highlightedIndex]);

  // The dropdown stays mounted while closed: center the highlighted cell once it is visible again
  useEffect(() => {
    if (!opened) {
      return undefined;
    }
    const frame = requestAnimationFrame(() =>
      virtualizer.scrollToOffset(getOffsetToCenter(model, highlightedIndex))
    );
    return () => cancelAnimationFrame(frame);
  }, [opened]);

  return (
    <ScrollArea
      h={GRID_HEIGHT}
      type="scroll"
      scrollbars="y"
      viewportRef={viewportRef}
      viewportProps={{ tabIndex: -1 }}
      onMouseLeave={() => onHover(-1)}
    >
      <div className={classes.grid} style={{ height: model.totalHeight }}>
        {virtualizer.getVirtualItems().map((item) => {
          const row = model.rows[item.index];
          const position = { transform: `translateY(${item.start}px)`, height: item.size };

          if (row.kind === 'label') {
            return (
              <Text
                key={row.key}
                size="xs"
                fw={500}
                className={classes.sectionLabel}
                style={position}
              >
                {row.label}
              </Text>
            );
          }

          return (
            <div key={row.key} className={classes.row} style={position}>
              {model.cells.slice(row.start, row.end).map((cell, offset) => {
                const index = row.start + offset;
                return (
                  <Combobox.Option
                    key={cell.key}
                    value={cell.key}
                    id={getOptionId(index)}
                    aria-label={cell.name}
                    className={classes.cell}
                    active={value?.name === cell.name && value.style === cell.style}
                    selected={index === highlightedIndex}
                    onClick={() => onPick(index)}
                    onMouseEnter={() => onHover(index)}
                  >
                    <IconByName name={cell.name} iconStyle={cell.style} size={22} stroke={1.5} />
                  </Combobox.Option>
                );
              })}
            </div>
          );
        })}
      </div>
    </ScrollArea>
  );
}

